class InsufficientFunds(Exception):
    pass


class AccountNotFound(Exception):
    pass


class Bank:
    def __init__(self):
        self.accounts = {}

    def open(self, name, deposit=0):
        if name in self.accounts:
            raise ValueError("이미 있는 계좌")
        self.accounts[name] = deposit

    def balance(self, name):
        if name not in self.accounts:
            raise AccountNotFound(name)
        return self.accounts[name]

    def transfer(self, src, dst, amount):
        if src not in self.accounts or dst not in self.accounts:
            raise AccountNotFound(src if src not in self.accounts else dst)
        if self.accounts[src] < amount:
            raise InsufficientFunds(src)
        self.accounts[src] -= amount
        self.accounts[dst] += amount

